package dev.edgeflow;
import android.content.ComponentName;import android.content.SharedPreferences;import org.json.*;import java.util.*;
/** Versioned launcher data; legacy component-only favorites are read without data loss. */
final class LauncherLayout {
 // Existing imported layouts accept any nonempty folder ID. It is only used as a map key.
 static boolean isFolderAction(String action){return action!=null&&action.startsWith("folder:")&&action.length()>7;}
 static final class Folder {String name;final ArrayList<String> items=new ArrayList<>();Folder(String n){name=n;}}
 final ArrayList<String> items=new ArrayList<>();final LinkedHashMap<String,Folder> folders=new LinkedHashMap<>();boolean recent;
 static String folderName(String value){String name=value==null?"":value.trim();if(name.isEmpty())name="文件夹";if(name.length()>256)throw new IllegalArgumentException("文件夹名称最多 256 个字符，请缩短名称后重试");return name;}
 static LauncherLayout load(SharedPreferences p){LauncherLayout l=new LauncherLayout();try{String raw=p.getString("layout_v2",null);if(raw==null){JSONArray a=new JSONArray(p.getString("favorites","[]"));for(int i=0;i<a.length();i++){String key=a.optString(i);if(ComponentName.unflattenFromString(key)!=null&&!l.items.contains("app:"+key))l.items.add("app:"+key);}l.recent=p.getBoolean("recent_page",false);return l;}JSONObject root=new JSONObject(raw);if(root.getInt("version")!=2)throw new JSONException("Unsupported launcher layout");l.recent=root.optBoolean("recent_page",false);JSONObject fs=root.optJSONObject("folders");if(fs!=null){Iterator<String> keys=fs.keys();while(keys.hasNext()){String id=keys.next();JSONObject f=fs.optJSONObject(id);if(f==null)continue;Folder folder=new Folder(f.optString("name","文件夹"));read(f.optJSONArray("items"),folder.items,false);l.folders.put(id,folder);}}read(root.optJSONArray("items"),l.items,true);l.items.removeIf(k->k.startsWith("folder:")&&!l.folders.containsKey(k.substring(7)));}catch(Exception e){android.util.Log.w("EdgeLauncher","Cannot read layout",e);}return l;}
 static void read(JSONArray a,ArrayList<String> out,boolean allowFolder){if(a==null)return;for(int i=0;i<a.length()&&out.size()<1000;i++){String k=a.optString(i);boolean valid=k.startsWith("app:")?ComponentName.unflattenFromString(k.substring(4))!=null:k.startsWith("action:")?Arrays.asList(ActionExecutor.IDS).contains(k.substring(7)):k.startsWith(ShortcutEntry.PREFIX)?ShortcutEntry.valid(k):allowFolder&&k.startsWith("folder:");if(valid&&!out.contains(k))out.add(k);}}
 void save(SharedPreferences p){try{JSONObject oldFolders=new JSONObject();try{oldFolders=new JSONObject(p.getString("layout_v2","{}")).optJSONObject("folders");}catch(JSONException ignored){}JSONObject fs=new JSONObject();for(Map.Entry<String,Folder> e:folders.entrySet()){String name=e.getValue().name;JSONObject old=oldFolders==null?null:oldFolders.optJSONObject(e.getKey());boolean unchangedLegacy=name!=null&&name.length()>256&&old!=null&&name.equals(old.optString("name"));if(!unchangedLegacy)folderName(name);fs.put(e.getKey(),new JSONObject().put("name",name).put("items",new JSONArray(e.getValue().items)));}p.edit().putString("layout_v2",new JSONObject().put("version",2).put("recent_page",recent).put("items",new JSONArray(items)).put("folders",fs).toString()).apply();}catch(JSONException e){throw new IllegalStateException(e);}}
 String createFolder(String name){String normalized=folderName(name);String id=UUID.randomUUID().toString();folders.put(id,new Folder(normalized));items.add("folder:"+id);return id;}
 /** Validate a raw SharedPreferences key/value JSON object before transactional import. */
 static void validatePreferences(JSONObject values)throws JSONException {
  Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();Object value=values.get(key);
   if(key.equals("layout_v2")){if(!(value instanceof String))throw new JSONException("layout_v2 must be a string");JSONObject root=new JSONObject((String)value);if(root.getInt("version")!=2)throw new JSONException("Unsupported launcher version");if(root.has("recent_page")&&!(root.get("recent_page") instanceof Boolean))throw new JSONException("recent_page must be boolean");JSONObject folders=root.getJSONObject("folders");Iterator<String> names=folders.keys();while(names.hasNext()){String id=names.next();if(id.isEmpty())throw new JSONException("Empty folder ID");JSONObject folder=folders.getJSONObject(id);Object name=folder.get("name");if(!(name instanceof String)||((String)name).trim().isEmpty())throw new JSONException("文件夹名称不能为空");if(((String)name).length()>256)throw new JSONException("文件夹名称超过 256 个字符，请在快速启动中重命名后重试");validateItems(folder.getJSONArray("items"),folders,false);}validateItems(root.getJSONArray("items"),folders,true);
   }else if(key.equals("favorites")){if(!(value instanceof String))throw new JSONException("favorites must be a string");JSONArray old=new JSONArray((String)value);HashSet<String> seen=new HashSet<>();for(int i=0;i<old.length();i++){String component=old.getString(i);if(ComponentName.unflattenFromString(component)==null||!seen.add(component))throw new JSONException("Invalid legacy favorite");}}
   else if(key.equals("shortcut_labels")){ShortcutPicker.validateLabels(value);}
   else if(key.equals("recent_page")){if(!(value instanceof Boolean))throw new JSONException("recent_page must be boolean");}
   else if(key.equals("columns")||key.equals("page")||key.equals("recent_limit")){if(!(value instanceof Number)||((Number)value).doubleValue()!=((Number)value).intValue())throw new JSONException("Launcher integer expected");int n=((Number)value).intValue();if(key.equals("columns")&&(n<2||n>5)||key.equals("page")&&(n<0||n>1000)||key.equals("recent_limit")&&(n!=5&&(n<8||n>13)&&n!=20&&n!=30))throw new JSONException("Launcher value out of range");}
   else throw new JSONException("Unknown launcher preference: "+key);
  }
 }
 private static void validateItems(JSONArray items,JSONObject folders,boolean allowFolders)throws JSONException{if(items.length()>1000)throw new JSONException("Too many launcher entries");HashSet<String> seen=new HashSet<>();for(int i=0;i<items.length();i++){Object value=items.get(i);if(!(value instanceof String))throw new JSONException("Launcher key must be string");String key=(String)value;boolean valid=key.startsWith("app:")?ComponentName.unflattenFromString(key.substring(4))!=null:key.startsWith("action:")?Arrays.asList(ActionExecutor.IDS).contains(key.substring(7)):key.startsWith(ShortcutEntry.PREFIX)?ShortcutEntry.valid(key):allowFolders&&key.startsWith("folder:")&&folders.has(key.substring(7));if(!valid||!seen.add(key))throw new JSONException("Invalid or duplicate launcher entry: "+key);}}
}
